裸机程序
与操作系统无关的OS类型的程序（Bare Metal program, 裸机程序）
// os/src/main.rs
![nostd]
![nomain]

mod langitems;

// os/src/langitems.rs
use core::panic::PanicInfo;

[panichandler]
fn panic(info: &PanicInfo) - ! {
    loop {}
}

链接时的内存布局定制
os/src/linker-qemu.ld
OUTPUTARCH(riscv)
ENTRY(start)
BASEADDRESS = 0x80200000;

SECTIONS
{
    . = BASEADDRESS;
    skernel = .;

    stext = .;
    .text : {
      (.text.entry)

分配并使用启动栈
os/src/linker-qemu.ld
.bss : {
    (.bss.stack)
    sbss = .;
    (.bss .bss.)
    (.sbss .sbss.)
}
ebss = .;
在链接脚本 linker.ld 中 .bss.stack 段最终会被汇集到 .bss 段中
.bss 段一般放置需要被初始化为零的数据

控制权转交：ASM -- Rust/C

将控制权转交给 Rust 代码，该入口点在 main.rs 中的rustmain函数
// os/src/main.rs  
pub fn rustmain() - ! {
    loop {}
}
- fn 关键字：函数； pub 关键字：对外可见，公共的
- loop 关键字：循环

清空bss段

清空bss段(未初始化数据段)
pub fn rustmain() - ! {
    clearbss(); //调用清空bss的函数clearbss()
}
fn clearbss() {
    extern "C" {
        fn sbss(); //bss段的起始地址
        fn ebss(); //bss段的结束地址
    }
    //对[sbss..ebss]这段内存空间清零
    (sbss as usize..ebss as usize).foreach(|a| {
        unsafe { (a as mut u8).writevolatile(0) }
    });
}

SBI服务编号
// os/src/sbi.rs
const SBISETTIMER: usize = 0;
const SBICONSOLEPUTCHAR: usize = 1;
const SBICONSOLEGETCHAR: usize = 2;
const SBICLEARIPI: usize = 3;
const SBISENDIPI: usize = 4;
const SBIREMOTEFENCEI: usize = 5;
const SBIREMOTESFENCEVMA: usize = 6;
const SBIREMOTESFENCEVMAASID: usize = 7;
const SBISHUTDOWN: usize = 8;
- usize 机器字大小的无符号整型

汇编级SBI调用

// os/src/sbi.rs
[inline(always)] //总是把函数展开
fn sbicall(which: usize, arg0: usize, arg1: usize, arg2: usize) - usize {
    let mut ret; //可修改的变量ret
    unsafe {
        asm!(//内嵌汇编
            "ecall", //切换到更高特权级的机器指令
            inlateout("x10") arg0 = ret, //SBI参数0&返回值
            in("x11") arg1,  //SBI参数1
            in("x12") arg2,  //SBI参数2
            in("x17") which, //SBI编号
        );
    }
    ret //返回ret值
}

SBI调用：输出字符

在屏幕上输出一个字符
// os/src/sbi.rs
pub fn consoleputchar(c: usize) {
    sbicall(SBICONSOLEPUTCHAR, c, 0, 0);
}
实现格式化输出
- 编写基于 consoleputchar 的 println! 宏

SBI调用：关机
// os/src/sbi.rs
pub fn shutdown() - ! {
    sbicall(SBISHUTDOWN, 0, 0, 0);
    panic!("It should shutdown!");
}
- panic!和println!是一个宏（类似C的宏），!是宏的标志

优雅地处理错误panic
[panichandler]
fn panic(info: &PanicInfo) - ! { //PnaicInfo是结构类型
    if let Some(location) = info.location() { //出错位置存在否？
        println!(
            "Panicked at {}:{} {}",
            location.file(), //出错的文件名
            location.line(), //出错的文件中的行数
            info.message().unwrap() //出错信息
        );
    } else {
        println!("Panicked: {}", info.message().unwrap());
    }
    shutdown() //关机
}

